## Load prerequisites libraries
import duckdb as db
import pandas as pd
import numpy as np
import pathlib
import glob

import config

## Create FS Data per customer
for customerName in config.customerList:
    for auditLog in config.auditList:
        if auditLog == 'sample_audit_decrypt':
            #RK remove the fields below for x8 - PREP_DATE_JSON,PREP_BY_JSON,PROJECT_JSON,SAMPLE_TYPE_JSON,PROTOCOL_LEVEL_JSON,VARIATION_JSON,TEST_LIST_JSON,INSTRUMENT_JSON,FACTOR_OPERATOR_JSON,ALIAS_NAME_JSON,CONTROL_2_JSON,
            DF = db.sql(f"select SOURCE_DB,SAMPLE_NUMBER,AUDIT_TIMESTAMP,AUDIT_COUNTER,TRANS_ORDER,AUDIT_TYPE,AUDIT_ACTION,TABLE_NAME,TABLE_KEY,REASON,RECORD_SIGNED,USER_NAME,USER_ROLE,T0083,T0083_SEVERITY,TEXT_ID_JSON,STATUS_JSON,OLD_STATUS_JSON,IN_SPEC_JSON,IN_CAL_JSON,RE_SAMPLE_JSON,ORIGINAL_SAMPLE_JSON,ALIQUOT_JSON,PARENT_SAMPLE_JSON,PARENT_ALIQUOT_JSON,LOGIN_DATE_JSON,LOGIN_BY_JSON,RECD_DATE_JSON,RECEIVED_BY_JSON,DATE_STARTED_JSON,STARTED_JSON,DATE_COMPLETED_JSON,DATE_REVIEWED_JSON,PRODUCT_VERSION_JSON,TEMPLATE_JSON,STANDARD_JSON,LOT_JSON,CHANGED_ON_JSON,PARTIAL_SPEC_JSON,PRIMARY_IN_SPEC_JSON,BATCH_JSON,RELEASED_JSON,RELEASED_BY_JSON,RELEASED_ON_JSON,IN_CONTROL_JSON,INVESTIGATED_JSON,MODIFIED_RESULTS_JSON,COMPOSITE_JSON,PARENT_COMPOSITE_JSON,HAS_FLAGS_JSON,SIGNED_JSON,TEST_NUMBER_JSON,CHARGE_ENTRY_JSON,ANALYSIS_JSON,VERSION_JSON,REPLICATE_COUNT_JSON,DATE_RECEIVED_JSON,PREP_JSON,REVIEWER_JSON,REPLICATE_TEST_JSON,ORDER_NUMBER_JSON,GROUP_NAME_JSON,RESOLVE_REQD_JSON,STAGE_JSON,RE_TESTED_JSON,ALIQUOTED_TO_JSON,ON_WORKSHEET_JSON,ANALYSIS_COUNT_JSON,BATCH_ORIGINAL_TEST_JSON,BATCH_PARENT_TEST_JSON,CHILD_OUT_SPEC_JSON,CROSS_SAMPLE_JSON,ORIGINAL_TEST_JSON,PARENT_TEST_JSON,RESULT_NUMBER_JSON,NAME_JSON,RESULT_TYPE_JSON,MINIMUM_JSON,MAXIMUM_JSON,ALLOW_OUT_JSON,FORMATTED_ENTRY_JSON,NUMERIC_ENTRY_JSON,PLACES_JSON,ENTERED_ON_JSON,ENTERED_BY_JSON,USES_CODES_JSON,AUTO_CALC_JSON,LIST_KEY_JSON,ALLOW_CANCEL_JSON,REPORTABLE_JSON,OPTIONAL_JSON,CODE_ENTERED_JSON,ROUND_JSON,STD_REAG_SAMPLE_JSON,DISPLAYED_JSON,ENTRY_QUALIFIER_JSON,USES_INSTRUMENT_JSON,HAS_ATTRIBUTES_JSON,ENTRY_TYPE_JSON,CONTROL_1_JSON,REPORTED_NAME_JSON,PREP_DATE_JSON,PREP_BY_JSON,PROJECT_JSON,SAMPLE_TYPE_JSON,PROTOCOL_LEVEL_JSON,VARIATION_JSON,TEST_LIST_JSON,INSTRUMENT_JSON,FACTOR_OPERATOR_JSON,ALIAS_NAME_JSON,CONTROL_2_JSON from read_parquet('{config.data_location}raw_output_{auditLog}_{customerName}.parquet')").to_df()
            
            DF.replace('█', np.nan, inplace=True)
            DF = DF.sort_values(by=['SOURCE_DB','SAMPLE_NUMBER','AUDIT_TIMESTAMP','AUDIT_COUNTER','TRANS_ORDER','TABLE_NAME','TABLE_KEY'],ignore_index=True).ffill() # 'AUDIT_TYPE' 'AUDIT_ACTION'
        
        elif auditLog == 'exp_audit_decrypt': 
            #RK fields not for x7 - ASSIGNED_TO_JSON,PRINTED_ON_JSON,PRINTED_BY_JSON,FILE_INSTR_1_JSON,FILE_INSTR_2_JSON,FILE_INSTR_3_JSON,FILE_INSTR_4_JSON,FILE_INSTR_5_JSON,DIRECT_INSTR_1_JSON,DIRECT_INSTR_2_JSON,DIRECT_INSTR_3_JSON,DIRECT_INSTR_4_JSON,DIRECT_INSTR_5_JSON,CHECKED_OUT_BY_JSON,CHECKED_OUT_ON_JSON,ENTER_BY_JSON,ENTERED_ON_JSON,,WITNESSED_BY_JSON,WITNESSED_ON_JSONINSTRUMENT_JSON,IMAGE_HASH_JSON,IMAGE_CONTENTS_JSON,
            DF = db.sql(f"select SOURCE_DB,AUDIT_COUNTER,TABLE_NAME,TABLE_KEY,AUDIT_TYPE,AUDIT_ACTION,REASON,TRANS_ORDER,USER_NAME,AUDIT_TIMESTAMP,RECORD_SIGNED,EXPERIMENT_NUMBER,WORKBOOK_NUMBER,WORKSHEET,COL_NUM,ROW_NUM,DOCUMENT_NUMBER,WORKBOOK_NUMBER_JSON,TEMPLATE_JSON,TEMPLATE_VERSION_JSON,STATUS_JSON,CREATED_BY_JSON,CREATED_ON_JSON,CHANGED_ON_JSON,CHANGED_BY_JSON,COMPLETED_ON_JSON,COMPLETED_BY_JSON,REVIEWED_ON_JSON,REVIEWED_BY_JSON,CANCELED_ON_JSON,CANCELED_BY_JSON,REMOVED_JSON,APPROVED_JSON,ARCHIVED_JSON,GROUP_NAME_JSON,DATA_MODIFIED_JSON,FILE_LINK_JSON,WORKFLOW_ID_JSON,ANALYSES_JSON,CHECKED_OUT_JSON,COMPLETED_JSON,REVIEWED_JSON,REVIEW_TYPE_JSON,REVIEW_COMMENT_JSON,SIGNED_JSON,SHEET_JSON,ROW_NUM_JSON,COL_NUM_JSON,NAME_JSON,VALUE_JSON,REVIEW_STATUS_JSON,MODIFIED_BY_JSON,MODIFIED_ON_JSON,WORKBOOK_OBJ_NO_JSON,FIELD_NAME_JSON,OBJECT_TYPE_JSON,OBJECT_ID_JSON,OBJECT_NAME_JSON,IN_SPEC_JSON,IN_CONTROL_JSON,IN_CAL_JSON,WITNESSED_JSON,CALCULATED_JSON,PASS_FLAG_JSON,PREVIOUS_VALUE_JSON,IMAGE_NUMBER_JSON,IMAGE_FORMAT_JSON,OBJECT_INDEX_JSON,SAMPLE_REP_JSON,TEST_REP_JSON,RESULT_REP_JSON,UPDATE_REFERENCE_JSON,MODIFIED_DATA_JSON,SHEET_1_JSON,SHEET_2_JSON,SHEET_3_JSON,ENTRY_CODE_JSON,SHEET_NAME_JSON,COMPLIANCE_FLAG_JSON,DATA_REVIEW_STATUS_JSON from read_parquet('{config.data_location}raw_output_{auditLog}_{customerName}.parquet')").to_df()
            
            DF.replace('█', np.nan, inplace=True)
            DF = DF.sort_values(by=['SOURCE_DB','EXPERIMENT_NUMBER','AUDIT_TIMESTAMP','AUDIT_COUNTER','TRANS_ORDER','TABLE_NAME','TABLE_KEY'],ignore_index=True).ffill() # 'AUDIT_TYPE' 'AUDIT_ACTION'

        elif auditLog == 'table_audit_decrypt':     
            DF = pd.read_parquet(f'{config.data_location}raw_output_{auditLog}_{customerName}.parquet', engine='pyarrow')
            
            #DF = db.sql(f"select * from read_parquet('{config.data_location}raw_output_{auditLog}_{customerName}.parquet')").df()
            DF.replace('█', np.nan, inplace=True)
            DF = DF.sort_values(by=['SOURCE_DB','TABLE_NAME','AUDIT_TIMESTAMP','AUDIT_COUNTER','TRANS_ORDER','PARENT_TABLE','PARENT_KEY'],ignore_index=True).ffill() # 'AUDIT_TYPE' 'AUDIT_ACTION'
        
        DF.dropna(how='all', axis=1, inplace=True)
        dirPath = f'{config.data_location}//FS_base_data//{auditLog}//'
        pathlib.Path(dirPath).mkdir(parents=True, exist_ok=True)
        fileName = dirPath + 'FS_base_data_'+ auditLog + '_' + customerName +'.parquet'
        DF.to_parquet(path=fileName, engine='pyarrow')

